import{_ as n,a0 as d,w as p,s as o,I as s,x as e,a1 as t,A as l,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"终端基础：在 Linux 中删除文件和文件夹 | LCTT x X-CMD","titleTemplate":false,"description":"终端基础：在 Linux 中删除文件和文件夹 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"终端基础：在 Linux 中删除文件和文件夹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"终端基础：在 Linux 中删除文件和文件夹 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230323.1 ⭐️ Terminal Basics 6 Delete Files and Folders in Linux","title":"终端基础：在 Linux 中删除文件和文件夹","tag":"202305","desc":""},"relativePath":"202305/20230323.1 ⭐️ Terminal Basics 6 Delete Files and Folders in Linux.md","filePath":"[post].md"}'),h={name:"202305/20230323.1 ⭐️ Terminal Basics 6 Delete Files and Folders in Linux.md"};function c(g,i,k,u,b,f){const a=d("Link");return p(),o("div",null,[i[20]||(i[20]=s("h1",{id:"终端基础-在-linux-中删除文件和文件夹",tabindex:"-1"},[e("终端基础：在 Linux 中删除文件和文件夹 "),s("a",{class:"header-anchor",href:"#终端基础-在-linux-中删除文件和文件夹","aria-label":"Permalink to “终端基础：在 Linux 中删除文件和文件夹”"},"​")],-1)),i[21]||(i[21]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/13/140619izbrl7owh9dr55lb.jpg",alt:""})],-1)),i[22]||(i[22]=s("blockquote",null,[s("p",null,"你已经学会了创建文件和目录。现在是时候学习如何在命令行中删除文件和文件夹了。")],-1)),s("p",null,[i[2]||(i[2]=e("在终端基础系列的前几章中，你学习了 ",-1)),t(a,{href:"https://linux.cn/article-15643-1.html"},{default:l(()=>[...i[0]||(i[0]=[e("创建新文件",-1)])]),_:1}),i[3]||(i[3]=e(" 和 ",-1)),t(a,{href:"https://linux.cn/article-15595-1.html"},{default:l(()=>[...i[1]||(i[1]=[e("目录",-1)])]),_:1}),i[4]||(i[4]=e("（文件夹）。",-1))]),i[23]||(i[23]=r(`<p>现在让我们看看如何在 Linux 终端中删除文件和文件夹。</p><h3 id="删除文件" tabindex="-1">删除文件 <a class="header-anchor" href="#删除文件" aria-label="Permalink to “删除文件”">​</a></h3><p>要删除文件，你可以按以下方式使用 <code>rm</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm filename_or_path</span></span></code></pre></div><p>如果文件已成功删除，你将看不到任何输出。</p><p>这是一个示例，其中我删除了一个名为 <code>new_file</code> 的文件。当我列出目录内容时，你可以看到 <code>new_file</code> 不再存在。</p><p><img src="https://itsfoss.com/content/images/2023/03/delete-files-linux-terminal.png" alt="Removing files in Linux terminal"></p><p>你还可以在同一命令中删除多个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm file1 file2 file3</span></span></code></pre></div><p>让我展示一个在单条命令中删除两个文件的示例。</p><p><img src="https://itsfoss.com/content/images/2023/03/remove-multiple-files-linux-terminal.png" alt="Deleting multiple files in single rm command"></p><h4 id="🏋️练习文件删除" tabindex="-1">🏋️练习文件删除 <a class="header-anchor" href="#🏋️练习文件删除" aria-label="Permalink to “🏋️练习文件删除”">​</a></h4><p>让我们练习一下刚刚学到的东西。创建一个名为 <code>practice_delete</code> 的目录并切换到该目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir practice_delete &amp;&amp; cd practice_delete</span></span></code></pre></div><p>现在创建一些空文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch file1 file2 file3</span></span></code></pre></div><p>删除 <code>file3</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm file3</span></span></code></pre></div><p>现在，让我们做一些额外的事情。运行此命令并更改 <code>file2</code> 的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod u-w file1 file2</span></span></code></pre></div><p>现在尝试删除 <code>file2</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm file2</span></span></code></pre></div><p>你是否看到消息 “<strong>remove write protected file</strong>”？ 那是因为你从这个文件中删除了写权限（用于修改）。</p><p>你可以<strong>按 <code>Y</code> 或回车键确认删除或按 <code>N</code> 拒绝删除。</strong></p><p>如果你不想看到这条消息并仍然删除它，你可以使用强制删除选项 <code>-f</code>。通过删除 <code>file1</code> 试试：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -f file1</span></span></code></pre></div><p>以下是上述所有示例的重放：</p><p><img src="https://itsfoss.com/content/images/2023/03/file-delete-example.svg" alt="Deleting files in Linux terminal"></p><blockquote><p>🚧 Linux 命令行中没有垃圾桶。一旦文件被删除，你就无法像在图形文件管理器中那样撤消将其从垃圾箱中取回的操作。因此，删除文件时要格外小心。</p></blockquote><h4 id="小心删除" tabindex="-1">小心删除 <a class="header-anchor" href="#小心删除" aria-label="Permalink to “小心删除”">​</a></h4><p>缺少垃圾桶使删除成为一种永久性的工作。这就是为什么你应该注意要删除的文件的原因。</p><p>有一个带 <code>-i</code> 选项的交互模式。有了这个，你会被要求确认删除。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -i filename</span></span></code></pre></div><p>当你根据特定模式删除多个文件时，这很有用。</p><p>这是一个示例，其中我以交互方式删除名称中匹配 <code>file_</code> 模式的所有文件。我删除了一些并在交互模式下保留了一些。</p><p><img src="https://itsfoss.com/content/images/2023/03/interactive-delete-example.svg" alt="Deleting files in interactive mode"></p><blockquote><p>💡 我建议切换到文件所在的目录，然后删除它们。这有助于减少由文件路径中的拼写错误引起的任何可能性。</p></blockquote><h3 id="删除目录" tabindex="-1">删除目录 <a class="header-anchor" href="#删除目录" aria-label="Permalink to “删除目录”">​</a></h3><p>在 Linux 中有专门的 <code>rmdir</code> 命令来删除目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rmdir dir_name</span></span></code></pre></div><p>但是，它只能删除空目录。如果目录中有任何文件或子目录，<code>rmdir</code> 命令将抛出错误。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rmdir dir2</span></span>
<span class="line"><span>rmdir: failed to remove &#39;dir2&#39;: Directory not empty</span></span></code></pre></div><p>这使得它在大多数情况下用处不大。</p><p>那么，如何删除非空文件夹呢？ 好吧，使用与之前删除文件相同的 <code>rm</code> 命令。</p><p>是的，相同的 <code>rm</code> 命令，但带有递归选项 <code>-r</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -r dir_name</span></span></code></pre></div><h4 id="🏋️练习文件夹删除" tabindex="-1">🏋️练习文件夹删除 <a class="header-anchor" href="#🏋️练习文件夹删除" aria-label="Permalink to “🏋️练习文件夹删除”">​</a></h4><p>让我们练习你学到的东西。</p><p>如果你还没有，请切换到 <code>practice_delete</code> 文件夹。现在，创建两个目录 <code>dir1</code> 和 <code>dir2</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir dir1 dir2</span></span></code></pre></div><p>在 <code>dir2</code> 中创建一个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch dir2/file</span></span></code></pre></div><p>现在尝试使用 <code>rmdir</code> 命令删除目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rmdir dir1</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rmdir dir2</span></span></code></pre></div><p>由于 <code>dir2</code> 不为空，<code>rmdir</code> 命令将失败。相反，使用带有递归选项的 <code>rm</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -r dir2</span></span></code></pre></div><p>以下是上述所有命令示例的重放：</p><p><img src="https://itsfoss.com/content/images/2023/03/folder-delete-example.svg" alt="Deleting folders in Linux"></p><blockquote><p>💡 交互式删除模式在使用 <code>rm</code> 命令的递归选项删除目录时更有帮助：</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm-ri dir_name</span></span></code></pre></div><p>因此，你学会了使用 Linux 命令删除文件和文件夹。是时候多练习了。</p><h3 id="测试你的知识" tabindex="-1">测试你的知识 <a class="header-anchor" href="#测试你的知识" aria-label="Permalink to “测试你的知识”">​</a></h3><p>准备一个如下所示的目录树：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── dir1</span></span>
<span class="line"><span>│   ├── file1</span></span>
<span class="line"><span>│   ├── file2</span></span>
<span class="line"><span>│   └── file3</span></span>
<span class="line"><span>├── dir2</span></span>
<span class="line"><span>├── dir3</span></span>
<span class="line"><span>└── file</span></span></code></pre></div><p>基本上，你在当前目录（<code>practice_delete</code>）中创建一个名为 <code>file</code> 的文件和三个目录 <code>dir1</code>、<code>dir2</code> 和 <code>dir3</code>。然后在 <code>dir1</code> 中创建文件 <code>file1</code>、<code>file2</code> 和 <code>file3</code>。</p><p>现在执行以下操作：</p><ul><li>删除 <code>file2</code>。</li><li>切换到 <code>dir3</code> 并强制删除上层目录中名为 <code>file</code> 的文件。</li><li>删除 dir1 的所有内容，但不删除目录本身。</li><li>列出 <code>dir</code> 的内容。</li></ul><p>一切进展顺利。你已经学习了一些基本知识，例如切换目录、检查目录内容、创建和删除文件和目录。在下一章中，你将学习如何在终端中复制文件和文件夹。敬请关注！</p><hr>`,70)),s("p",null,[i[6]||(i[6]=e("via: ",-1)),t(a,{href:"https://itsfoss.com/delete-files-folders-linux/"},{default:l(()=>[...i[5]||(i[5]=[e("https://itsfoss.com/delete-files-folders-linux/",-1)])]),_:1})]),s("p",null,[i[11]||(i[11]=e("作者：",-1)),t(a,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...i[7]||(i[7]=[e("Abhishek Prakash",-1)])]),_:1}),i[12]||(i[12]=e(" 选题：",-1)),t(a,{href:"https://github.com/lkxed/"},{default:l(()=>[...i[8]||(i[8]=[e("lkxed",-1)])]),_:1}),i[13]||(i[13]=e(" 译者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:l(()=>[...i[9]||(i[9]=[e("geekpi",-1)])]),_:1}),i[14]||(i[14]=e(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[10]||(i[10]=[e("wxy",-1)])]),_:1})]),s("p",null,[i[17]||(i[17]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[15]||(i[15]=[e("LCTT",-1)])]),_:1}),i[18]||(i[18]=e(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...i[16]||(i[16]=[e("Linux中国",-1)])]),_:1}),i[19]||(i[19]=e(" 荣誉推出",-1))])])}const C=n(h,[["render",c]]);export{y as __pageData,C as default};
